INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.CREATI.SELF_AWARENESS.GENDER', 'CRE.G3.CREATI.SELF_AWARENESS', 'cre', 3, 'Identify themselves as male or female as God created them (Genesis 1:27)', ARRAY['CRE.G3.CREATI.SELF_AWARENESS.a']::text[], 'Says that God created people male and female in his own image (Genesis 1:27), names himself or herself as a boy (male) or a girl (female), and says both boys and girls are made by God and equally loved. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what Genesis 1:27 says","who created male and female","boy or girl"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.CREATI.SELF_AWARENESS.COPE_FEELINGS', 'CRE.G3.CREATI.SELF_AWARENESS', 'cre', 3, 'Describe how to cope with happy and sad feelings', ARRAY['CRE.G3.CREATI.SELF_AWARENESS.b']::text[], 'Describes good ways of coping with feelings: when happy, share joy, sing, thank God; when sad, angry or afraid, pray, talk to a parent, teacher or friend, sing, rest, play; and knows that hitting, breaking things or hiding the feeling forever do not help. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G3.RUBRIC.1.1, CRE.G3.RUBRIC.1.2, CRE.G3.RUBRIC.1.3, CRE.G3.RUBRIC.1.4, CRE.G3.RUBRIC.1.5), never as a phone question: c) make the right choices guided by the word of God.', '["what to do when sad","good or bad way to cope","which feeling"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.CREATI.MY_FAMILY.FAMILY_MEMBERS', 'CRE.G3.CREATI.MY_FAMILY', 'cre', 3, 'Name members of the nuclear and the extended family', ARRAY['CRE.G3.CREATI.MY_FAMILY.a']::text[], 'Names members of the nuclear family (father, mother, brothers, sisters) and the extended family (grandparents, uncles, aunts, cousins), says how each is related (my mother''s mother is my grandmother; my father''s brother is my uncle), and reads a simple family tree. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G3.RUBRIC.1.1, CRE.G3.RUBRIC.1.2, CRE.G3.RUBRIC.1.3, CRE.G3.RUBRIC.1.4, CRE.G3.RUBRIC.1.5), never as a phone question: b) draw the family tree to understand family relationships.', '["nuclear or extended","who is this to you","family tree: who goes here"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.CREATI.ADAM_AND_EVE.FIRST_PEOPLE', 'CRE.G3.CREATI.ADAM_AND_EVE', 'cre', 3, 'Recognise God as the creator of Adam and Eve and describe how they disobeyed God (Genesis 2-3)', ARRAY['CRE.G3.CREATI.ADAM_AND_EVE.a', 'CRE.G3.CREATI.ADAM_AND_EVE.b']::text[], 'Says God formed Adam from the dust of the ground and breathed life into him (Genesis 2:7), made Eve from Adam''s rib (Genesis 2:21-22), told them not to eat from the tree of the knowledge of good and evil (Genesis 2:16-17), and that the serpent tempted Eve, she ate and gave to Adam, and he ate (Genesis 3:6). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["who made Adam and how","what God told them","what Adam and Eve did"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.CREATI.ADAM_AND_EVE.DISOBEY_RESULTS', 'CRE.G3.CREATI.ADAM_AND_EVE', 'cre', 3, 'State four results of Adam''s disobedience (Genesis 3:16-23)', ARRAY['CRE.G3.CREATI.ADAM_AND_EVE.c']::text[], 'States results of the disobedience: they knew they were naked and hid from God, the ground was cursed so man would work hard (sweat) for food (Genesis 3:17-19), pain for the woman in childbirth (3:16), people would return to dust (die) (3:19), and they were sent out of the Garden of Eden (3:23). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what happened after they ate","true or false","which is a result"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.BIBLE_WORD', 'CRE.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF', 'cre', 3, 'Differentiate the Bible from other books (2 Timothy 3:16)', ARRAY['CRE.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.a']::text[], 'Says the Bible is different from other books because all Scripture is God-breathed (inspired by God) and useful for teaching and correcting (2 Timothy 3:16), it is God''s word that guides Christians, and it is handled and read with respect; other books are written by people for learning or stories. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["how is the Bible different","what 2 Timothy 3:16 says","Bible or another book"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.NEW_TESTAMENT', 'CRE.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF', 'cre', 3, 'State the number of books in the New Testament and name the four Gospels', ARRAY['CRE.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.b', 'CRE.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.c']::text[], 'States that the New Testament has 27 books (and the Old Testament 39, 66 in all) and names the four Gospels in order: Matthew, Mark, Luke and John; knows they tell of the life of Jesus. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["how many books in the New Testament","name the Gospels in order","is this a Gospel"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_MOSES_AND_TH.MOSES_BUSH', 'CRE.G3.THE_BI.BIBLE_STORY_MOSES_AND_TH', 'cre', 3, 'Retell the story of Moses and the burning bush and mention lessons from it (Exodus 3:1-6)', ARRAY['CRE.G3.THE_BI.BIBLE_STORY_MOSES_AND_TH.a', 'CRE.G3.THE_BI.BIBLE_STORY_MOSES_AND_TH.b']::text[], 'Retells Exodus 3:1-6: Moses looked after the flock of Jethro his father-in-law near Horeb, the mountain of God; he saw a bush on fire that did not burn up; God called "Moses! Moses!" and he answered "Here I am"; God told him to take off his sandals because the place was holy ground; Moses hid his face. Lessons: God speaks to people, we respect holy places, we obey God, we answer when God calls. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what happened next","what God told Moses","a lesson from the story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_THE_BIG_FISH.JONAH', 'CRE.G3.THE_BI.BIBLE_STORY_THE_BIG_FISH', 'cre', 3, 'Narrate the story of Jonah and list the results of his disobedience (Jonah 1-2)', ARRAY['CRE.G3.THE_BI.BIBLE_STORY_THE_BIG_FISH.a', 'CRE.G3.THE_BI.BIBLE_STORY_THE_BIG_FISH.b']::text[], 'Narrates Jonah 1:1-4, 15, 17 and 2:10: God told Jonah to go to Nineveh; Jonah ran away and boarded a ship to Tarshish; God sent a great storm; the sailors threw Jonah into the sea and it became calm; a big fish swallowed him and he was inside three days and three nights; the fish spat him out on dry land. Results: the storm, being thrown into the sea, being swallowed by the fish. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["where God sent Jonah","what happened next","a result of his disobedience"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_NAAMAN_IS_HE.NAAMAN', 'CRE.G3.THE_BI.BIBLE_STORY_NAAMAN_IS_HE', 'cre', 3, 'Retell the healing of Naaman and mention lessons from it (2 Kings 5:1-14)', ARRAY['CRE.G3.THE_BI.BIBLE_STORY_NAAMAN_IS_HE.a', 'CRE.G3.THE_BI.BIBLE_STORY_NAAMAN_IS_HE.b', 'CRE.G3.THE_BI.BIBLE_STORY_NAAMAN_IS_HE.c']::text[], 'Retells 2 Kings 5:1-14: Naaman, commander of the army of the king of Aram (Syria), had leprosy; a young Israelite servant girl said a prophet in Samaria could heal him; Elisha sent a messenger telling him to wash seven times in the Jordan; Naaman was angry but his servants persuaded him; he washed and his skin became clean like a young boy''s. Lessons: God heals, obey God''s word, be humble, even a child can help others. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["who told Naaman about the prophet","what Elisha told him","a lesson from the story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_THE_THREE_HE.THREE_HEBREWS', 'CRE.G3.THE_BI.BIBLE_STORY_THE_THREE_HE', 'cre', 3, 'Narrate the story of the three Hebrew men and list lessons from it (Daniel 3)', ARRAY['CRE.G3.THE_BI.BIBLE_STORY_THE_THREE_HE.a', 'CRE.G3.THE_BI.BIBLE_STORY_THE_THREE_HE.b']::text[], 'Narrates Daniel 3: King Nebuchadnezzar made a golden image and ordered all to bow; Shadrach, Meshach and Abednego refused because they worshipped only God; they were thrown into a blazing furnace; the king saw four men walking in the fire; they came out unharmed, not even smelling of smoke; the king praised their God. Lessons: worship only God, God protects those who trust him, be brave to do right. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["why they were thrown into the fire","what the king saw","a lesson"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_ELISHA_AND_T.ELISHA_BOYS', 'CRE.G3.THE_BI.BIBLE_STORY_ELISHA_AND_T', 'cre', 3, 'Retell the story of Elisha and the boys and mention lessons from it (2 Kings 2:23-24)', ARRAY['CRE.G3.THE_BI.BIBLE_STORY_ELISHA_AND_T.a', 'CRE.G3.THE_BI.BIBLE_STORY_ELISHA_AND_T.b']::text[], 'Retells 2 Kings 2:23-24: as Elisha went up to Bethel, some boys came out of the town and jeered at him, "Get out of here, baldhead!"; Elisha called down a curse in the name of the Lord, and two bears came out of the woods and mauled forty-two of the boys. Lessons: respect the elderly, respect God''s servants, do not mock or call people names, our words have results. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the boys said","what happened","a lesson"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_LI.THE_BIRTH_OF_JESUS_CHRIS.WISE_MEN', 'CRE.G3.THE_LI.THE_BIRTH_OF_JESUS_CHRIS', 'cre', 3, 'Retell the story of the wise men and name the hometown of Jesus (Matthew 2)', ARRAY['CRE.G3.THE_LI.THE_BIRTH_OF_JESUS_CHRIS.a', 'CRE.G3.THE_LI.THE_BIRTH_OF_JESUS_CHRIS.b']::text[], 'Retells Matthew 2:1-11: wise men from the East saw a star and came to Jerusalem asking where the king of the Jews was born; they were sent to Bethlehem; the star led them to the house where Jesus was; they bowed, worshipped and gave gold, frankincense and myrrh; warned in a dream, they went home another way. Names Nazareth as Jesus'' hometown (Matthew 2:23; Luke 2:39), though he was born in Bethlehem. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what led the wise men","where Jesus grew up","what happened next"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_LI.THE_GOOD_SAMARITAN.GOOD_SAMARITAN', 'CRE.G3.THE_LI.THE_GOOD_SAMARITAN', 'cre', 3, 'Narrate the story of the Good Samaritan and list lessons from it (Luke 10:30-37)', ARRAY['CRE.G3.THE_LI.THE_GOOD_SAMARITAN.a', 'CRE.G3.THE_LI.THE_GOOD_SAMARITAN.b']::text[], 'Narrates Luke 10:30-37: a man going down from Jerusalem to Jericho was attacked by robbers and left half dead; a priest passed by on the other side, then a Levite; a Samaritan took pity, bandaged his wounds with oil and wine, put him on his own donkey, took him to an inn and paid the innkeeper two silver coins. Lessons: help people in need, love your neighbour, be kind to everyone, even people different from us. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["who passed by","what the Samaritan did","a lesson"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_LI.THE_LITTLE_BOY_WITH_FIVE.LOAVES_FISH', 'CRE.G3.THE_LI.THE_LITTLE_BOY_WITH_FIVE', 'cre', 3, 'Retell the miracle of the five loaves and two fish and state lessons from it (John 6:1-14)', ARRAY['CRE.G3.THE_LI.THE_LITTLE_BOY_WITH_FIVE.a', 'CRE.G3.THE_LI.THE_LITTLE_BOY_WITH_FIVE.b']::text[], 'Retells John 6:1-14: a large crowd followed Jesus; Andrew found a boy with five small barley loaves and two small fish; Jesus had the people sit down, gave thanks and shared the food; about five thousand men ate as much as they wanted; the disciples gathered twelve baskets of leftovers. Lessons: share what we have, God provides, give thanks before eating, do not waste food. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the boy had","what Jesus did","how much was left"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_LI.JESUS_CHRIST_WALKS_ON_WA.WALKS_ON_WATER', 'CRE.G3.THE_LI.JESUS_CHRIST_WALKS_ON_WA', 'cre', 3, 'Narrate the miracle of Jesus walking on water and list lessons from it (Matthew 14:22-33)', ARRAY['CRE.G3.THE_LI.JESUS_CHRIST_WALKS_ON_WA.a', 'CRE.G3.THE_LI.JESUS_CHRIST_WALKS_ON_WA.b']::text[], 'Narrates Matthew 14:22-33: the disciples were in a boat far from land, battered by waves; Jesus came walking on the lake; they were terrified and thought he was a ghost; he said "Take courage! It is I. Do not be afraid"; Peter walked on the water to him but, seeing the wind, was afraid and began to sink and cried "Lord, save me!"; Jesus caught him; the wind stopped and they worshipped him. Lessons: have faith, call on Jesus when afraid, Jesus has power over nature. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the disciples thought they saw","what happened to Peter","a lesson"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_LI.RAISING_OF_JAIRUS_DAUGHT.JAIRUS', 'CRE.G3.THE_LI.RAISING_OF_JAIRUS_DAUGHT', 'cre', 3, 'Retell the raising of Jairus'' daughter, list lessons and recognise Jesus'' power over life and death (Mark 5:35-43)', ARRAY['CRE.G3.THE_LI.RAISING_OF_JAIRUS_DAUGHT.a', 'CRE.G3.THE_LI.RAISING_OF_JAIRUS_DAUGHT.b', 'CRE.G3.THE_LI.RAISING_OF_JAIRUS_DAUGHT.c']::text[], 'Retells Mark 5:35-43: messengers told Jairus his daughter had died; Jesus said "Don''t be afraid; just believe"; he took Peter, James and John; people laughed when he said she was asleep; he took her hand and said "Talitha koum" (Little girl, I say to you, get up); she got up and walked; she was twelve years old; he told them to give her something to eat. Lessons: have faith, do not give up, Jesus has power over life and death, Jesus cares for children. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the messengers said","what Jesus said and did","a lesson"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_LI.EASTER.EASTER', 'CRE.G3.THE_LI.EASTER', 'cre', 3, 'Mention the importance of celebrating Easter and the events that take place during Easter', ARRAY['CRE.G3.THE_LI.EASTER.a', 'CRE.G3.THE_LI.EASTER.b']::text[], 'Says Christians celebrate Easter to remember the death of Jesus on Good Friday and his rising from the dead on Easter Sunday (Matthew 28:1-6: the women found the tomb empty and the angel said "He is not here; he has risen"), and names Easter events and activities: Palm Sunday, Good Friday services, Easter Sunday services, singing, reading the Bible, prayers, a public holiday with family. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["why Christians celebrate Easter","what happened on Good Friday or Easter Sunday","an Easter activity"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.CHRIST.HONESTY.ANANIAS', 'CRE.G3.CHRIST.HONESTY', 'cre', 3, 'Narrate the story of Ananias and Sapphira and explain why we respect other people''s property (Acts 5:1-11)', ARRAY['CRE.G3.CHRIST.HONESTY.a', 'CRE.G3.CHRIST.HONESTY.c']::text[], 'Narrates Acts 5:1-11: Ananias and his wife Sapphira sold land, kept back part of the money and brought the rest to the apostles, pretending it was all; Peter said they had lied to God, not only to people; both died. Explains why we respect other people''s property: it belongs to them, taking it is stealing, God wants honesty, and others trust us. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (the strand''s rubric in the printed KICD design; not in this file), never as a phone question: b) practise honesty by taking offerings given by parents to church.', '["what Ananias and Sapphira did","honest or dishonest","why respect property"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.CHRIST.THANKFULNESS.THANK_GOD', 'CRE.G3.CHRIST.THANKFULNESS', 'cre', 3, 'List ways of thanking God and reasons for thanking God for family, friends and teachers (Psalm 136:1)', ARRAY['CRE.G3.CHRIST.THANKFULNESS.a', 'CRE.G3.CHRIST.THANKFULNESS.b']::text[], 'Lists ways of thanking God (praying, singing praise, giving offerings, saying grace before meals, helping others, caring for creation) and reasons to thank God for family (they love and feed us), friends (they play with and help us) and teachers (they teach and guide us); says Psalm 136:1: give thanks to the Lord, for he is good; his love endures forever. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["a way of thanking God","a reason to thank God for this person","what Psalm 136:1 says"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.CHRIST.FORGIVENESS.UNFORGIVING_SERVANT', 'CRE.G3.CHRIST.FORGIVENESS', 'cre', 3, 'Retell the story of the unforgiving servant (Matthew 18:21-35)', ARRAY['CRE.G3.CHRIST.FORGIVENESS.a']::text[], 'Retells Matthew 18:21-35: Peter asked if he should forgive seven times and Jesus said seventy-seven times; a servant owed the king a huge debt, begged, and the king forgave all of it; the same servant grabbed a fellow servant who owed him a little, refused to forgive and had him thrown into prison; the king was angry and punished the unforgiving servant. Lesson: forgive others as God forgives us. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (the strand''s rubric in the printed KICD design; not in this file), never as a phone question: b) dramatise the story of the unforgiving servant.', '["how many times to forgive","what the servant did","what the king did"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.CHRIST.TRUST.TRUSTED_ADULTS', 'CRE.G3.CHRIST.TRUST', 'cre', 3, 'Identify people they can trust for safety and name people to report to if touched inappropriately', ARRAY['CRE.G3.CHRIST.TRUST.a', 'CRE.G3.CHRIST.TRUST.b']::text[], 'Names people a child can trust for safety (parents or guardians, the class teacher, the head teacher, a pastor, a police officer, a nurse) and three people to report to if anyone touches them in a way that is wrong or asks them to keep a secret touch (a parent or guardian, a teacher, the head teacher, the police, Childline 116); knows it is never the child''s fault and that you keep telling until someone helps. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (the strand''s rubric in the printed KICD design; not in this file), never as a phone question: c) stay safe by reporting people who molest them.', '["who can you trust","whom would you tell","what to do if someone touches you wrongly"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.CHRIST.RESPONSIBILITY.CHORES', 'CRE.G3.CHRIST.RESPONSIBILITY', 'cre', 3, 'Say why a responsible child does chores at home without expecting a reward (Colossians 3:23)', ARRAY['CRE.G3.CHRIST.RESPONSIBILITY.c']::text[], 'Names chores a child does at home (sweeping, washing utensils, fetching water, making the bed, feeding animals, caring for younger siblings) and says why a responsible child does them without expecting a reward: helping is part of being a family, it pleases God (Colossians 3:23: work as for the Lord), and it shows love; also says keeping clean and correcting wrong kindly are responsible acts. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (the strand''s rubric in the printed KICD design; not in this file), never as a phone question: a) practise cleanliness at home and school; b) demonstrate responsibility by correcting those in the wrong.', '["why do chores without reward","responsible or not","name a chore"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_CH.PRAYER.LORDS_PRAYER', 'CRE.G3.THE_CH.PRAYER', 'cre', 3, 'Know the Lord''s Prayer and appropriate postures in prayer (Matthew 6:9-13)', ARRAY['CRE.G3.THE_CH.PRAYER.b']::text[], 'Knows that Jesus taught the Lord''s Prayer (Matthew 6:9-13), puts its lines in order (Our Father in heaven, hallowed be your name; your kingdom come, your will be done; give us today our daily bread; forgive us our debts as we forgive our debtors; lead us not into temptation but deliver us from the evil one), and names respectful postures Christians use (kneeling, standing, bowing the head, closing the eyes, folding the hands), all ways of respecting God. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (the strand''s rubric in the printed KICD design; not in this file), never as a phone question: a) recite the Lord’s prayer in Mathew 6:9-13.', '["what comes next in the Lord''s Prayer","a respectful posture","who taught the prayer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_CH.THE_HOLY_SPIRIT.PENTECOST', 'CRE.G3.THE_CH.THE_HOLY_SPIRIT', 'cre', 3, 'Retell the coming of the Holy Spirit at Pentecost and identify his work in a Christian''s life (Acts 2:1-4)', ARRAY['CRE.G3.THE_CH.THE_HOLY_SPIRIT.a', 'CRE.G3.THE_CH.THE_HOLY_SPIRIT.b']::text[], 'Retells Acts 2:1-4: on the day of Pentecost the disciples were together in one place; a sound like a violent wind came from heaven; what looked like tongues of fire rested on each of them; they were filled with the Holy Spirit and spoke in other languages. Identifies the work of the Holy Spirit: he helps, comforts, guides, teaches, gives strength and helps Christians pray. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what happened at Pentecost","a work of the Holy Spirit","what the disciples saw and heard"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G3.THE_CH.THE_HOLY_SPIRIT.FRUIT_SPIRIT', 'CRE.G3.THE_CH.THE_HOLY_SPIRIT', 'cre', 3, 'Identify five fruit of the Holy Spirit (Galatians 5:22-23)', ARRAY['CRE.G3.THE_CH.THE_HOLY_SPIRIT.c']::text[], 'Names at least five of the fruit of the Spirit (Galatians 5:22-23: love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, self-control), knows they are ways of behaving, not fruits we eat, and spots them in everyday actions (sharing is kindness, waiting your turn is patience). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["is this a fruit of the Spirit","which fruit is shown in this story","odd one out"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G3.CREATI.SELF_AWARENESS.GENDER', 'CRES.G2.CREATI.SELF_AWARENESS.SELF_LIKES', 'skill', 'essential', 'Saying what one likes about oneself comes before seeing oneself as God made one. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G3.CREATI.SELF_AWARENESS.GENDER', 'CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.SKY_CREATION', 'skill', 'essential', 'God as the creator of everything, from Grade 2. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G3.CREATI.SELF_AWARENESS.COPE_FEELINGS', 'CRES.G3.CREATI.SELF_AWARENESS.GENDER', 'skill', 'essential', 'Knowing oneself as God made one comes before handling one''s feelings. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G3.CREATI.SELF_AWARENESS.COPE_FEELINGS', 'CRES.G2.CREATI.SELF_AWARENESS.SELF_LIKES', 'skill', 'essential', 'Knowing what one likes about oneself. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G3.CREATI.MY_FAMILY.FAMILY_MEMBERS', 'CRES.G2.CREATI.MY_FAMILY.EXTENDED_FAMILY', 'skill', 'essential', 'Naming family members, from Grade 2. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G3.CREATI.MY_FAMILY.FAMILY_MEMBERS', 'CRE.G2.CREATI.MY_FAMILY.d', 'outcome', 'essential', 'The extended family met in Grade 2. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G3.CREATI.ADAM_AND_EVE.FIRST_PEOPLE', 'CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.SKY_CREATION', 'skill', 'essential', 'God as the creator of the sky, sun, moon and stars comes before the creation of people. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
