INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.SELF_AWARENESS.GENDER.M_C3_GEN_BOYS_BETTER', 'CRES.G3.CREATI.SELF_AWARENESS.GENDER', 'Thinks God loves boys more than girls (or girls more than boys).', '{"question":"Whom did God create in his image, according to Genesis 1:27?","wrong_answer":"Only boys","correct_answer":"Both male and female"}'::jsonb, 'The child has heard one gender praised more at home or in play.', 'Offer "Only boys" beside "Both male and female" and ask the child to choose.', 'Read Genesis 1:27 slowly: male and female he created them. Both in God''s image.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.SELF_AWARENESS.GENDER.M_C3_GEN_PEOPLE_MADE_SELVES', 'CRES.G3.CREATI.SELF_AWARENESS.GENDER', 'Thinks parents alone decide whether a baby is a boy or a girl.', '{"question":"Who created people male and female?","wrong_answer":"Parents choose","correct_answer":"God"}'::jsonb, 'Babies come from parents, so parents seem to decide everything.', 'Offer "Parents choose" beside "God" and ask the child to choose.', 'Link Genesis 1:27 and Psalm 139:13: God forms each child.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.SELF_AWARENESS.GENDER.M_C3_GEN_ACTIVITIES', 'CRES.G3.CREATI.SELF_AWARENESS.GENDER', 'Thinks a child is a boy or a girl because of the chores or games he or she does.', '{"question":"Wanjiru plays football. Is she still a girl?","wrong_answer":"No, football is for boys","correct_answer":"Yes, she is a girl God made"}'::jsonb, 'Activities are often split by gender at home.', 'Offer "No, football is for boys" beside "Yes, she is a girl God made" and ask the child to choose.', 'List activities both boys and girls do. Being a boy or girl is how God made you, not what you play.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.SELF_AWARENESS.GENDER.M_C3_GEN_IMAGE_LOOKS', 'CRES.G3.CREATI.SELF_AWARENESS.GENDER', 'Thinks "made in God''s image" means people look exactly like God''s face.', '{"question":"What does \"made in God''s image\" teach us?","wrong_answer":"We look exactly like God","correct_answer":"Each person is special to God and can love and do good like him"}'::jsonb, 'Image is used at home for a photo.', 'Offer "We look exactly like God" beside "Each person is special to God and can love and do good like him" and ask the child to choose.', 'Talk about a child "taking after" a parent in kindness, not only looks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.SELF_AWARENESS.COPE_FEELINGS.M_C3_COPE_HIDE', 'CRES.G3.CREATI.SELF_AWARENESS.COPE_FEELINGS', 'Thinks a sad feeling should be hidden and never told to anyone.', '{"question":"You feel very sad. What can you do?","wrong_answer":"Keep it inside and tell nobody","correct_answer":"Pray and talk to a parent or teacher"}'::jsonb, 'The child has been told not to cry or complain.', 'Offer "Keep it inside and tell nobody" beside "Pray and talk to a parent or teacher" and ask the child to choose.', 'Role-play telling a trusted adult. Say: sharing a sad feeling helps.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.SELF_AWARENESS.COPE_FEELINGS.M_C3_COPE_HIT', 'CRES.G3.CREATI.SELF_AWARENESS.COPE_FEELINGS', 'Thinks hitting back is the way to stop feeling angry.', '{"question":"A friend takes your pencil and you feel angry. What should you do?","wrong_answer":"Hit him","correct_answer":"Calm down, talk to him or tell the teacher"}'::jsonb, 'Hitting back is common in play and seems fair.', 'Offer "Hit him" beside "Calm down, talk to him or tell the teacher" and ask the child to choose.', 'Practise calm steps: breathe, count, speak, get help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.SELF_AWARENESS.COPE_FEELINGS.M_C3_COPE_HAPPY_SHOW', 'CRES.G3.CREATI.SELF_AWARENESS.COPE_FEELINGS', 'Thinks being happy means showing off or laughing at others.', '{"question":"You got the best marks. What is a good way to show you are happy?","wrong_answer":"Laugh at those who failed","correct_answer":"Thank God and share your joy kindly"}'::jsonb, 'Winning games often comes with teasing.', 'Offer "Laugh at those who failed" beside "Thank God and share your joy kindly" and ask the child to choose.', 'Contrast two pictures: a child laughing at others and a child thanking God and helping.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.SELF_AWARENESS.COPE_FEELINGS.M_C3_COPE_PRAY_NOT', 'CRES.G3.CREATI.SELF_AWARENESS.COPE_FEELINGS', 'Thinks God does not care about children''s small feelings, so prayer is only for big problems.', '{"question":"Can a child pray to God when sad about a small thing?","wrong_answer":"No, God is busy","correct_answer":"Yes, God cares about how we feel"}'::jsonb, 'God is pictured as caring only about big matters.', 'Offer "No, God is busy" beside "Yes, God cares about how we feel" and ask the child to choose.', 'Read 1 Peter 5:7 (cast all your anxiety on him) in simple words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.MY_FAMILY.FAMILY_MEMBERS.M_C3_FAM_GRANDMA_NUCLEAR', 'CRES.G3.CREATI.MY_FAMILY.FAMILY_MEMBERS', 'Puts grandparents in the nuclear family because they live in the same home.', '{"question":"Is a grandmother part of the nuclear or the extended family?","wrong_answer":"Nuclear","correct_answer":"Extended"}'::jsonb, 'Many children live with grandparents in one home.', 'Offer "Nuclear" beside "Extended" and ask the child to choose.', 'Draw the nuclear family in the middle circle (father, mother, children) and the extended family around it. Grandmother may live with you and still be extended.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.MY_FAMILY.FAMILY_MEMBERS.M_C3_FAM_COUSIN', 'CRES.G3.CREATI.MY_FAMILY.FAMILY_MEMBERS', 'Thinks a cousin is a brother or sister.', '{"question":"Your aunt''s son is your...?","wrong_answer":"Brother","correct_answer":"Cousin"}'::jsonb, 'Cousins are often called brothers and sisters at home.', 'Offer "Brother" beside "Cousin" and ask the child to choose.', 'Trace on a family tree: aunt, then her son, a cousin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.MY_FAMILY.FAMILY_MEMBERS.M_C3_FAM_UNCLE_SIDE', 'CRES.G3.CREATI.MY_FAMILY.FAMILY_MEMBERS', 'Thinks an uncle is only the father''s brother, not the mother''s.', '{"question":"Is your mother''s brother your uncle?","wrong_answer":"No, uncles are father''s brothers","correct_answer":"Yes"}'::jsonb, 'Different words are used in some home languages.', 'Offer "No, uncles are father''s brothers" beside "Yes" and ask the child to choose.', 'Show both sides of a family tree with uncles on each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.MY_FAMILY.FAMILY_MEMBERS.M_C3_FAM_ONLY_PARENTS', 'CRES.G3.CREATI.MY_FAMILY.FAMILY_MEMBERS', 'Thinks a family must have both a father and a mother, so a child with a guardian has no family.', '{"question":"Achieng lives with her grandmother. Does she have a family?","wrong_answer":"No","correct_answer":"Yes, her grandmother and those who care for her are her family"}'::jsonb, 'Pictures in books show one shape of family.', 'Offer "No" beside "Yes, her grandmother and those who care for her are her family" and ask the child to choose.', 'Show many family pictures. Say: family is the people God gives to love and care for us.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.ADAM_AND_EVE.FIRST_PEOPLE.M_C3_AE_APPLE', 'CRES.G3.CREATI.ADAM_AND_EVE.FIRST_PEOPLE', 'Says the Bible names the fruit as an apple.', '{"question":"What does Genesis say about the fruit Adam and Eve ate?","wrong_answer":"It was an apple","correct_answer":"It was the fruit of the tree of the knowledge of good and evil"}'::jsonb, 'Pictures and cartoons show an apple.', 'Offer "It was an apple" beside "It was the fruit of the tree of the knowledge of good and evil" and ask the child to choose.', 'Read Genesis 2:17 and 3:6. The tree is named, not the kind of fruit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.ADAM_AND_EVE.FIRST_PEOPLE.M_C3_AE_ADAM_FIRST_ATE', 'CRES.G3.CREATI.ADAM_AND_EVE.FIRST_PEOPLE', 'Thinks Adam ate first and gave the fruit to Eve.', '{"question":"Who ate the fruit first?","wrong_answer":"Adam","correct_answer":"Eve, then she gave some to Adam"}'::jsonb, 'Adam is named first in the story, so the child thinks he acted first.', 'Offer "Adam" beside "Eve, then she gave some to Adam" and ask the child to choose.', 'Act out Genesis 3:6 in order with two children.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.ADAM_AND_EVE.FIRST_PEOPLE.M_C3_AE_EVE_FROM_DUST', 'CRES.G3.CREATI.ADAM_AND_EVE.FIRST_PEOPLE', 'Thinks Eve was made from dust like Adam.', '{"question":"What did God use to make Eve?","wrong_answer":"Dust","correct_answer":"A rib from Adam"}'::jsonb, 'The child knows one way God made people.', 'Offer "Dust" beside "A rib from Adam" and ask the child to choose.', 'Read Genesis 2:21-22 with a picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.ADAM_AND_EVE.FIRST_PEOPLE.M_C3_AE_GOD_ALLOWED', 'CRES.G3.CREATI.ADAM_AND_EVE.FIRST_PEOPLE', 'Thinks God allowed them to eat from every tree.', '{"question":"Which tree did God tell Adam not to eat from?","wrong_answer":"None, they could eat from all","correct_answer":"The tree of the knowledge of good and evil"}'::jsonb, 'The garden was full of good trees, so the rule is forgotten.', 'Offer "None, they could eat from all" beside "The tree of the knowledge of good and evil" and ask the child to choose.', 'Read Genesis 2:16-17: every tree except one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.ADAM_AND_EVE.DISOBEY_RESULTS.M_C3_AE_NO_RESULT', 'CRES.G3.CREATI.ADAM_AND_EVE.DISOBEY_RESULTS', 'Thinks nothing happened because God forgave them at once.', '{"question":"What happened to Adam and Eve after they disobeyed?","wrong_answer":"Nothing, God forgave them","correct_answer":"They were sent out of the Garden of Eden"}'::jsonb, 'Children are taught God forgives, so punishment is forgotten.', 'Offer "Nothing, God forgave them" beside "They were sent out of the Garden of Eden" and ask the child to choose.', 'Read Genesis 3:23. God still cared (he made them clothes), but there were results.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.ADAM_AND_EVE.DISOBEY_RESULTS.M_C3_AE_ANIMALS_CURSE', 'CRES.G3.CREATI.ADAM_AND_EVE.DISOBEY_RESULTS', 'Thinks the ground was blessed, not cursed, so food came easily.', '{"question":"After the disobedience, how would man get food?","wrong_answer":"Easily, the ground was blessed","correct_answer":"By hard work and sweat, because the ground was cursed"}'::jsonb, 'The child mixes up the words blessed and cursed.', 'Offer "Easily, the ground was blessed" beside "By hard work and sweat, because the ground was cursed" and ask the child to choose.', 'Read Genesis 3:17-19 and act out hard digging.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.ADAM_AND_EVE.DISOBEY_RESULTS.M_C3_AE_HID_PLAY', 'CRES.G3.CREATI.ADAM_AND_EVE.DISOBEY_RESULTS', 'Thinks Adam and Eve hid from God because they were playing.', '{"question":"Why did Adam and Eve hide from God?","wrong_answer":"They were playing hide and seek","correct_answer":"They were afraid and ashamed because they had disobeyed"}'::jsonb, 'Hiding is a game for children.', 'Offer "They were playing hide and seek" beside "They were afraid and ashamed because they had disobeyed" and ask the child to choose.', 'Ask how a child feels after breaking a rule. Link with Genesis 3:8-10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CREATI.ADAM_AND_EVE.DISOBEY_RESULTS.M_C3_AE_GARDEN_STAY', 'CRES.G3.CREATI.ADAM_AND_EVE.DISOBEY_RESULTS', 'Thinks Adam and Eve stayed in the garden and only lost one tree.', '{"question":"Where did Adam and Eve live after they disobeyed?","wrong_answer":"Still in the Garden of Eden","correct_answer":"Outside the garden"}'::jsonb, 'The story ends for the child at eating the fruit.', 'Offer "Still in the Garden of Eden" beside "Outside the garden" and ask the child to choose.', 'Draw the garden with a gate and Adam and Eve outside (Genesis 3:23-24).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.BIBLE_WORD.M_C3_BIB_STORYBOOK', 'CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.BIBLE_WORD', 'Thinks the Bible is just a storybook like other storybooks.', '{"question":"How is the Bible different from a storybook?","wrong_answer":"It is not different","correct_answer":"It is God''s word, inspired by God (2 Timothy 3:16)"}'::jsonb, 'The Bible has stories and pictures like storybooks.', 'Offer "It is not different" beside "It is God''s word, inspired by God (2 Timothy 3:16)" and ask the child to choose.', 'Read 2 Timothy 3:16. Compare who gave each book its message.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.BIBLE_WORD.M_C3_BIB_BIG_BOOK', 'CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.BIBLE_WORD', 'Thinks the Bible is different only because it is big or has thin pages.', '{"question":"What makes the Bible special?","wrong_answer":"It is big and thick","correct_answer":"It is God''s word that guides us"}'::jsonb, 'Its size and look are what the child notices.', 'Offer "It is big and thick" beside "It is God''s word that guides us" and ask the child to choose.', 'Show a small pocket Bible. Still God''s word. Size does not make it special.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.BIBLE_WORD.M_C3_BIB_PASTOR_WROTE', 'CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.BIBLE_WORD', 'Thinks the pastor or one person wrote the whole Bible.', '{"question":"Who inspired the writing of the Bible?","wrong_answer":"The pastor","correct_answer":"God, through many writers"}'::jsonb, 'The child hears the Bible read by the pastor.', 'Offer "The pastor" beside "God, through many writers" and ask the child to choose.', 'Say: many people wrote over many years, and God inspired them (2 Timothy 3:16).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.BIBLE_WORD.M_C3_BIB_ONLY_CHURCH', 'CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.BIBLE_WORD', 'Thinks the Bible is useful only in church, not in daily life.', '{"question":"When can the Bible guide us?","wrong_answer":"Only in church","correct_answer":"Every day, at home and at school"}'::jsonb, 'The Bible is seen mainly at church.', 'Offer "Only in church" beside "Every day, at home and at school" and ask the child to choose.', 'Read 2 Timothy 3:16 (useful for teaching) and Psalm 119:105 (a lamp to my feet).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.NEW_TESTAMENT.M_C3_NT_39', 'CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.NEW_TESTAMENT', 'Gives 39 as the number of New Testament books.', '{"question":"How many books are in the New Testament?","wrong_answer":"39","correct_answer":"27"}'::jsonb, 'The child learnt 39 for the Old Testament in Grade 2.', 'Offer "39" beside "27" and ask the child to choose.', 'Write OT 39, NT 27, total 66 on a two-part bookshelf.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.NEW_TESTAMENT.M_C3_NT_ACTS_GOSPEL', 'CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.NEW_TESTAMENT', 'Names Acts or Genesis as one of the four Gospels.', '{"question":"Which of these is a Gospel: Acts or Mark?","wrong_answer":"Acts","correct_answer":"Mark"}'::jsonb, 'Acts comes right after the Gospels and Genesis is a well-known book.', 'Offer "Acts" beside "Mark" and ask the child to choose.', 'Sing the Gospels in order: Matthew, Mark, Luke, John; then Acts comes next, a different kind of book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.NEW_TESTAMENT.M_C3_NT_ORDER', 'CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.NEW_TESTAMENT', 'Names the Gospels in the wrong order (John first).', '{"question":"Which Gospel comes first in the New Testament?","wrong_answer":"John","correct_answer":"Matthew"}'::jsonb, 'John is a familiar name and is said first.', 'Offer "John" beside "Matthew" and ask the child to choose.', 'Use the first letters M, M, L, J in a chant and on flashcards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.NEW_TESTAMENT.M_C3_NT_GOSPEL_OT', 'CRES.G3.THE_BI.THE_BIBLE_AS_THE_WORD_OF.NEW_TESTAMENT', 'Thinks the Gospels are in the Old Testament.', '{"question":"In which part of the Bible are the four Gospels?","wrong_answer":"The Old Testament","correct_answer":"The New Testament"}'::jsonb, 'Both testaments are new words to the child.', 'Offer "The Old Testament" beside "The New Testament" and ask the child to choose.', 'Open a Bible at Matthew: the New Testament begins here.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_MOSES_AND_TH.MOSES_BUSH.M_C3_MOS_BUSH_BURNT', 'CRES.G3.THE_BI.BIBLE_STORY_MOSES_AND_TH.MOSES_BUSH', 'Thinks the bush burnt up to ashes.', '{"question":"What was strange about the burning bush?","wrong_answer":"It burnt to ashes","correct_answer":"It was on fire but did not burn up"}'::jsonb, 'Every fire the child has seen burns things up.', 'Offer "It burnt to ashes" beside "It was on fire but did not burn up" and ask the child to choose.', 'Read Exodus 3:2 and ask what is strange. Draw a bush with flames but green leaves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_MOSES_AND_TH.MOSES_BUSH.M_C3_MOS_SHOES_DIRTY', 'CRES.G3.THE_BI.BIBLE_STORY_MOSES_AND_TH.MOSES_BUSH', 'Thinks Moses removed his sandals because they were dirty.', '{"question":"Why did God tell Moses to take off his sandals?","wrong_answer":"They were dirty","correct_answer":"The place was holy ground"}'::jsonb, 'At home shoes are removed when dirty.', 'Offer "They were dirty" beside "The place was holy ground" and ask the child to choose.', 'Read Exodus 3:5. Talk about showing respect in a holy place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_MOSES_AND_TH.MOSES_BUSH.M_C3_MOS_COWS', 'CRES.G3.THE_BI.BIBLE_STORY_MOSES_AND_TH.MOSES_BUSH', 'Thinks Moses was looking after cows or his own animals.', '{"question":"Whose flock was Moses looking after?","wrong_answer":"His own cows","correct_answer":"The flock of Jethro, his father-in-law"}'::jsonb, 'Herding in the child''s area is of cattle.', 'Offer "His own cows" beside "The flock of Jethro, his father-in-law" and ask the child to choose.', 'Read Exodus 3:1 and draw sheep and goats.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_MOSES_AND_TH.MOSES_BUSH.M_C3_MOS_RAN_AWAY', 'CRES.G3.THE_BI.BIBLE_STORY_MOSES_AND_TH.MOSES_BUSH', 'Thinks Moses ran away when God called.', '{"question":"What did Moses answer when God called him?","wrong_answer":"He ran away","correct_answer":"Here I am"}'::jsonb, 'Fear of fire makes running seem natural.', 'Offer "He ran away" beside "Here I am" and ask the child to choose.', 'Read Exodus 3:4. Compare with Samuel''s "Speak, for your servant is listening".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_THE_BIG_FISH.JONAH.M_C3_JON_WHALE_LIED', 'CRES.G3.THE_BI.BIBLE_STORY_THE_BIG_FISH.JONAH', 'Thinks Jonah went to Nineveh at once and the fish was a reward.', '{"question":"What did Jonah do when God told him to go to Nineveh?","wrong_answer":"He went at once","correct_answer":"He ran away on a ship to Tarshish"}'::jsonb, 'The child expects Bible people always obey.', 'Offer "He went at once" beside "He ran away on a ship to Tarshish" and ask the child to choose.', 'Show a map arrow pointing away from Nineveh. Read Jonah 1:3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_THE_BIG_FISH.JONAH.M_C3_JON_SAILORS_BAD', 'CRES.G3.THE_BI.BIBLE_STORY_THE_BIG_FISH.JONAH', 'Thinks the sailors threw Jonah into the sea for fun or to be cruel.', '{"question":"Why did the sailors throw Jonah into the sea?","wrong_answer":"To be cruel","correct_answer":"The storm would stop; Jonah himself told them to (Jonah 1:12)"}'::jsonb, 'Throwing someone in the sea sounds cruel.', 'Offer "To be cruel" beside "The storm would stop; Jonah himself told them to (Jonah 1:12)" and ask the child to choose.', 'Read Jonah 1:12, 15: Jonah told them, and the sea became calm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_THE_BIG_FISH.JONAH.M_C3_JON_DAYS', 'CRES.G3.THE_BI.BIBLE_STORY_THE_BIG_FISH.JONAH', 'Says Jonah was inside the fish for one day or seven days.', '{"question":"How long was Jonah inside the fish?","wrong_answer":"Seven days","correct_answer":"Three days and three nights"}'::jsonb, 'The child guesses a number often heard in stories.', 'Offer "Seven days" beside "Three days and three nights" and ask the child to choose.', 'Read Jonah 1:17 and count three days and nights on fingers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_THE_BIG_FISH.JONAH.M_C3_JON_FISH_ATE', 'CRES.G3.THE_BI.BIBLE_STORY_THE_BIG_FISH.JONAH', 'Thinks the fish ate Jonah and he died.', '{"question":"What happened to Jonah after three days?","wrong_answer":"He died inside the fish","correct_answer":"The fish spat him out onto dry land"}'::jsonb, 'Fish swallow food, so Jonah seems eaten.', 'Offer "He died inside the fish" beside "The fish spat him out onto dry land" and ask the child to choose.', 'Read Jonah 2:10. God kept Jonah alive.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_NAAMAN_IS_HE.NAAMAN.M_C3_NAA_ELISHA_TOUCH', 'CRES.G3.THE_BI.BIBLE_STORY_NAAMAN_IS_HE.NAAMAN', 'Thinks Elisha came out and touched Naaman to heal him.', '{"question":"How did Elisha tell Naaman to be healed?","wrong_answer":"He came out and touched him","correct_answer":"He sent a messenger: wash seven times in the Jordan"}'::jsonb, 'In healing stories the healer often touches the sick person.', 'Offer "He came out and touched him" beside "He sent a messenger: wash seven times in the Jordan" and ask the child to choose.', 'Read 2 Kings 5:10-11. Naaman expected a show and got a message.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_NAAMAN_IS_HE.NAAMAN.M_C3_NAA_ONCE', 'CRES.G3.THE_BI.BIBLE_STORY_NAAMAN_IS_HE.NAAMAN', 'Says Naaman washed once or three times.', '{"question":"How many times did Naaman wash in the Jordan?","wrong_answer":"Once","correct_answer":"Seven times"}'::jsonb, 'Washing once is enough at home.', 'Offer "Once" beside "Seven times" and ask the child to choose.', 'Count seven dips aloud with hand movements.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_NAAMAN_IS_HE.NAAMAN.M_C3_NAA_GIRL_NOBODY', 'CRES.G3.THE_BI.BIBLE_STORY_NAAMAN_IS_HE.NAAMAN', 'Thinks the servant girl did nothing important because she was a child.', '{"question":"Who first told Naaman''s family about the prophet?","wrong_answer":"Nobody, Naaman knew","correct_answer":"A young Israelite servant girl"}'::jsonb, 'Children are rarely heroes in stories they hear.', 'Offer "Nobody, Naaman knew" beside "A young Israelite servant girl" and ask the child to choose.', 'Read 2 Kings 5:2-3. Ask: what did a small girl do for a great man?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_NAAMAN_IS_HE.NAAMAN.M_C3_NAA_RIVER_MAGIC', 'CRES.G3.THE_BI.BIBLE_STORY_NAAMAN_IS_HE.NAAMAN', 'Thinks the Jordan river water healed him by itself.', '{"question":"Who healed Naaman?","wrong_answer":"The river water","correct_answer":"God, when Naaman obeyed"}'::jsonb, 'The washing is the action the child sees.', 'Offer "The river water" beside "God, when Naaman obeyed" and ask the child to choose.', 'Say: Naaman had washed in other rivers. God healed him when he obeyed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_THE_THREE_HE.THREE_HEBREWS.M_C3_HEB_LIONS', 'CRES.G3.THE_BI.BIBLE_STORY_THE_THREE_HE.THREE_HEBREWS', 'Mixes the story with Daniel and says they were thrown to lions.', '{"question":"Where were Shadrach, Meshach and Abednego thrown?","wrong_answer":"Into the lions'' den","correct_answer":"Into a blazing furnace"}'::jsonb, 'Both stories are in Daniel and end with God saving.', 'Offer "Into the lions'' den" beside "Into a blazing furnace" and ask the child to choose.', 'Put two pictures side by side: Daniel and lions, three men and fire.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_THE_THREE_HE.THREE_HEBREWS.M_C3_HEB_BOWED', 'CRES.G3.THE_BI.BIBLE_STORY_THE_THREE_HE.THREE_HEBREWS', 'Thinks the three men bowed to the statue to save their lives.', '{"question":"What did the three men do when told to bow to the golden image?","wrong_answer":"They bowed","correct_answer":"They refused and worshipped only God"}'::jsonb, 'Obeying the king seems the safe thing.', 'Offer "They bowed" beside "They refused and worshipped only God" and ask the child to choose.', 'Read Daniel 3:16-18. They chose God over the king.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_THE_THREE_HE.THREE_HEBREWS.M_C3_HEB_FOUR_GUARD', 'CRES.G3.THE_BI.BIBLE_STORY_THE_THREE_HE.THREE_HEBREWS', 'Thinks the fourth man in the fire was a guard or another prisoner.', '{"question":"Who was the fourth man in the fire?","wrong_answer":"A guard","correct_answer":"One sent by God to protect them (an angel; Daniel 3:28)"}'::jsonb, 'The child expects a normal person.', 'Offer "A guard" beside "One sent by God to protect them (an angel; Daniel 3:28)" and ask the child to choose.', 'Read Daniel 3:25, 28: God sent his angel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_THE_THREE_HE.THREE_HEBREWS.M_C3_HEB_BURNT', 'CRES.G3.THE_BI.BIBLE_STORY_THE_THREE_HE.THREE_HEBREWS', 'Thinks they came out with burns.', '{"question":"How were the three men when they came out?","wrong_answer":"Badly burnt","correct_answer":"Unharmed, not even smelling of smoke"}'::jsonb, 'Fire always burns.', 'Offer "Badly burnt" beside "Unharmed, not even smelling of smoke" and ask the child to choose.', 'Read Daniel 3:27 and ask what was strange.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_ELISHA_AND_T.ELISHA_BOYS.M_C3_ELI_NAMES_FUN', 'CRES.G3.THE_BI.BIBLE_STORY_ELISHA_AND_T.ELISHA_BOYS', 'Thinks calling an old person names is harmless fun.', '{"question":"The boys called Elisha \"baldhead\". Was that right?","wrong_answer":"Yes, it was just fun","correct_answer":"No, it was disrespectful"}'::jsonb, 'Teasing is common in play.', 'Offer "Yes, it was just fun" beside "No, it was disrespectful" and ask the child to choose.', 'Ask how an old person feels when laughed at. Read the lesson: respect the elderly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_ELISHA_AND_T.ELISHA_BOYS.M_C3_ELI_NUMBER', 'CRES.G3.THE_BI.BIBLE_STORY_ELISHA_AND_T.ELISHA_BOYS', 'Gets the number of boys or bears wrong (one bear, two boys).', '{"question":"How many bears came out of the woods?","wrong_answer":"One","correct_answer":"Two"}'::jsonb, 'The child remembers bears but not numbers.', 'Offer "One" beside "Two" and ask the child to choose.', 'Read 2 Kings 2:24 and draw two bears and the number 42.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_ELISHA_AND_T.ELISHA_BOYS.M_C3_ELI_BALD_BAD', 'CRES.G3.THE_BI.BIBLE_STORY_ELISHA_AND_T.ELISHA_BOYS', 'Thinks Elisha was wrong to be bald, so the boys had a reason.', '{"question":"Is being bald a reason to laugh at someone?","wrong_answer":"Yes, it looks funny","correct_answer":"No, we never laugh at how someone looks"}'::jsonb, 'Children laugh at differences.', 'Offer "Yes, it looks funny" beside "No, we never laugh at how someone looks" and ask the child to choose.', 'Talk about how God made each person. Link with Psalm 139:14.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_BI.BIBLE_STORY_ELISHA_AND_T.ELISHA_BOYS.M_C3_ELI_LESSON_BEARS', 'CRES.G3.THE_BI.BIBLE_STORY_ELISHA_AND_T.ELISHA_BOYS', 'Gives "beware of bears" as the lesson instead of respect.', '{"question":"What is the main lesson of Elisha and the boys?","wrong_answer":"Beware of bears","correct_answer":"Respect the elderly and God''s servants"}'::jsonb, 'The bears are the most vivid part of the story.', 'Offer "Beware of bears" beside "Respect the elderly and God''s servants" and ask the child to choose.', 'Ask: what did the boys do wrong? The lesson is about that.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.THE_BIRTH_OF_JESUS_CHRIS.WISE_MEN.M_C3_WISE_HOMETOWN_BETH', 'CRES.G3.THE_LI.THE_BIRTH_OF_JESUS_CHRIS.WISE_MEN', 'Names Bethlehem as Jesus'' hometown.', '{"question":"Which town was Jesus'' hometown, where he grew up?","wrong_answer":"Bethlehem","correct_answer":"Nazareth"}'::jsonb, 'Bethlehem is the town of the Christmas story.', 'Offer "Bethlehem" beside "Nazareth" and ask the child to choose.', 'Show two towns on a map: born in Bethlehem, grew up in Nazareth (Matthew 2:23).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.THE_BIRTH_OF_JESUS_CHRIS.WISE_MEN.M_C3_WISE_STABLE', 'CRES.G3.THE_LI.THE_BIRTH_OF_JESUS_CHRIS.WISE_MEN', 'Thinks the wise men came to the stable the night Jesus was born, with the shepherds.', '{"question":"Where did the wise men find Jesus, according to Matthew 2:11?","wrong_answer":"In the stable on the night he was born","correct_answer":"In a house"}'::jsonb, 'Nativity plays put everyone at the manger together.', 'Offer "In the stable on the night he was born" beside "In a house" and ask the child to choose.', 'Read Matthew 2:11: they came to the house. Shepherds came on the birth night (Luke 2).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.THE_BIRTH_OF_JESUS_CHRIS.WISE_MEN.M_C3_WISE_THREE_KNOWN', 'CRES.G3.THE_LI.THE_BIRTH_OF_JESUS_CHRIS.WISE_MEN', 'States as Bible fact that there were exactly three wise men with names.', '{"question":"Does Matthew say how many wise men came?","wrong_answer":"Yes, three, and gives their names","correct_answer":"No, it names three gifts but not the number of men"}'::jsonb, 'Songs and plays always show three.', 'Offer "Yes, three, and gives their names" beside "No, it names three gifts but not the number of men" and ask the child to choose.', 'Read Matthew 2:1, 11 and count the gifts, not the men.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.THE_BIRTH_OF_JESUS_CHRIS.WISE_MEN.M_C3_WISE_HEROD_HELP', 'CRES.G3.THE_LI.THE_BIRTH_OF_JESUS_CHRIS.WISE_MEN', 'Thinks King Herod wanted to worship Jesus too.', '{"question":"Why did the wise men go home another way?","wrong_answer":"Herod wanted to worship Jesus","correct_answer":"God warned them in a dream not to go back to Herod"}'::jsonb, 'Herod said he wanted to worship, and the child believes him.', 'Offer "Herod wanted to worship Jesus" beside "God warned them in a dream not to go back to Herod" and ask the child to choose.', 'Read Matthew 2:12. Herod did not mean what he said.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.THE_GOOD_SAMARITAN.GOOD_SAMARITAN.M_C3_SAM_PRIEST_HELPED', 'CRES.G3.THE_LI.THE_GOOD_SAMARITAN.GOOD_SAMARITAN', 'Thinks the priest or the Levite helped the man because they were religious.', '{"question":"Who helped the wounded man?","wrong_answer":"The priest","correct_answer":"The Samaritan"}'::jsonb, 'The child expects religious leaders to be the helpers.', 'Offer "The priest" beside "The Samaritan" and ask the child to choose.', 'Act out the three passers-by. Ask who stopped.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.THE_GOOD_SAMARITAN.GOOD_SAMARITAN.M_C3_SAM_NEIGHBOUR_NEAR', 'CRES.G3.THE_LI.THE_GOOD_SAMARITAN.GOOD_SAMARITAN', 'Thinks a neighbour is only a person living next door.', '{"question":"In the story, who was a neighbour to the wounded man?","wrong_answer":"The person who lived next to him","correct_answer":"The one who showed him mercy, the Samaritan"}'::jsonb, 'Neighbour means the next house in everyday use.', 'Offer "The person who lived next to him" beside "The one who showed him mercy, the Samaritan" and ask the child to choose.', 'Read Luke 10:36-37. A neighbour is anyone we help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.THE_GOOD_SAMARITAN.GOOD_SAMARITAN.M_C3_SAM_ONLY_FRIENDS', 'CRES.G3.THE_LI.THE_GOOD_SAMARITAN.GOOD_SAMARITAN', 'Thinks we should help only people we know or who are like us.', '{"question":"Should we help someone from another community who is hurt?","wrong_answer":"No, only our own people","correct_answer":"Yes, help anyone in need"}'::jsonb, 'Children help friends first.', 'Offer "No, only our own people" beside "Yes, help anyone in need" and ask the child to choose.', 'Say that Samaritans and Jews did not get along, yet he helped.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.THE_GOOD_SAMARITAN.GOOD_SAMARITAN.M_C3_SAM_LEFT_INN', 'CRES.G3.THE_LI.THE_GOOD_SAMARITAN.GOOD_SAMARITAN', 'Thinks the Samaritan left the man on the road after bandaging him.', '{"question":"Where did the Samaritan take the man?","wrong_answer":"He left him on the road","correct_answer":"To an inn, and paid for his care"}'::jsonb, 'Bandaging seems to finish the help.', 'Offer "He left him on the road" beside "To an inn, and paid for his care" and ask the child to choose.', 'Read Luke 10:34-35. Count the steps of help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.THE_LITTLE_BOY_WITH_FIVE.LOAVES_FISH.M_C3_LOAF_NUMBERS', 'CRES.G3.THE_LI.THE_LITTLE_BOY_WITH_FIVE.LOAVES_FISH', 'Swaps the numbers (two loaves and five fish).', '{"question":"What did the boy have?","wrong_answer":"Two loaves and five fish","correct_answer":"Five loaves and two fish"}'::jsonb, 'Both numbers are small and easy to swap.', 'Offer "Two loaves and five fish" beside "Five loaves and two fish" and ask the child to choose.', 'Hold up five fingers for loaves and two for fish while saying it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.THE_LITTLE_BOY_WITH_FIVE.LOAVES_FISH.M_C3_LOAF_DISCIPLES_FOOD', 'CRES.G3.THE_LI.THE_LITTLE_BOY_WITH_FIVE.LOAVES_FISH', 'Thinks the food came from the disciples'' own bags.', '{"question":"Who gave the loaves and fish?","wrong_answer":"The disciples","correct_answer":"A small boy"}'::jsonb, 'Disciples are the helpers in many stories.', 'Offer "The disciples" beside "A small boy" and ask the child to choose.', 'Read John 6:9. Andrew found the boy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.THE_LITTLE_BOY_WITH_FIVE.LOAVES_FISH.M_C3_LOAF_NO_LEFT', 'CRES.G3.THE_LI.THE_LITTLE_BOY_WITH_FIVE.LOAVES_FISH', 'Thinks the food was just enough with nothing left.', '{"question":"How much food was left over?","wrong_answer":"Nothing","correct_answer":"Twelve baskets"}'::jsonb, 'The child expects shared food to run out.', 'Offer "Nothing" beside "Twelve baskets" and ask the child to choose.', 'Read John 6:13 and count twelve baskets.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.THE_LITTLE_BOY_WITH_FIVE.LOAVES_FISH.M_C3_LOAF_THANKS', 'CRES.G3.THE_LI.THE_LITTLE_BOY_WITH_FIVE.LOAVES_FISH', 'Thinks Jesus shared the food without praying.', '{"question":"What did Jesus do before sharing the food?","wrong_answer":"He shared it at once","correct_answer":"He gave thanks to God"}'::jsonb, 'The child focuses on the sharing.', 'Offer "He shared it at once" beside "He gave thanks to God" and ask the child to choose.', 'Read John 6:11. Practise saying grace before snack.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.JESUS_CHRIST_WALKS_ON_WA.WALKS_ON_WATER.M_C3_WAT_GHOST', 'CRES.G3.THE_LI.JESUS_CHRIST_WALKS_ON_WA.WALKS_ON_WATER', 'Thinks the disciples were happy when they first saw Jesus on the water.', '{"question":"How did the disciples feel when they saw Jesus walking on the water?","wrong_answer":"Happy","correct_answer":"Terrified; they thought he was a ghost"}'::jsonb, 'Seeing Jesus is always good news to the child.', 'Offer "Happy" beside "Terrified; they thought he was a ghost" and ask the child to choose.', 'Read Matthew 14:26 and act out fright at a shape in the dark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.JESUS_CHRIST_WALKS_ON_WA.WALKS_ON_WATER.M_C3_WAT_PETER_SANK_START', 'CRES.G3.THE_LI.JESUS_CHRIST_WALKS_ON_WA.WALKS_ON_WATER', 'Thinks Peter sank as soon as he stepped out.', '{"question":"When did Peter begin to sink?","wrong_answer":"At once","correct_answer":"When he saw the wind and was afraid"}'::jsonb, 'Walking on water seems impossible from the start.', 'Offer "At once" beside "When he saw the wind and was afraid" and ask the child to choose.', 'Read Matthew 14:29-30: he walked, then looked at the wind.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.JESUS_CHRIST_WALKS_ON_WA.WALKS_ON_WATER.M_C3_WAT_STORM_CALMS', 'CRES.G3.THE_LI.JESUS_CHRIST_WALKS_ON_WA.WALKS_ON_WATER', 'Mixes it with calming the storm and says Jesus was asleep in the boat.', '{"question":"Where was Jesus when the disciples were in the boat at night?","wrong_answer":"Asleep in the boat","correct_answer":"On the mountain praying, then walking on the water to them"}'::jsonb, 'Both stories have a boat and wind.', 'Offer "Asleep in the boat" beside "On the mountain praying, then walking on the water to them" and ask the child to choose.', 'Put the two story pictures side by side and spot differences.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.JESUS_CHRIST_WALKS_ON_WA.WALKS_ON_WATER.M_C3_WAT_LESSON_SWIM', 'CRES.G3.THE_LI.JESUS_CHRIST_WALKS_ON_WA.WALKS_ON_WATER', 'Gives "learn to swim" or "do not go on boats" as the lesson.', '{"question":"What is a lesson from Jesus walking on water?","wrong_answer":"Do not go on boats","correct_answer":"Have faith in Jesus and call on him when afraid"}'::jsonb, 'The danger of water stands out.', 'Offer "Do not go on boats" beside "Have faith in Jesus and call on him when afraid" and ask the child to choose.', 'Ask what Peter cried out and what Jesus said about faith.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.RAISING_OF_JAIRUS_DAUGHT.JAIRUS.M_C3_JAI_SICK_ONLY', 'CRES.G3.THE_LI.RAISING_OF_JAIRUS_DAUGHT.JAIRUS', 'Thinks Jesus only healed a sick girl, not raised her from death.', '{"question":"What had happened to Jairus'' daughter when Jesus arrived?","wrong_answer":"She was a little sick","correct_answer":"She had died"}'::jsonb, 'Healing stories are more common, and death is hard for a child to think about.', 'Offer "She was a little sick" beside "She had died" and ask the child to choose.', 'Read Mark 5:35. Say gently: she had died, and Jesus brought her back to life.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.RAISING_OF_JAIRUS_DAUGHT.JAIRUS.M_C3_JAI_AGE', 'CRES.G3.THE_LI.RAISING_OF_JAIRUS_DAUGHT.JAIRUS', 'Gives a wrong age, such as a baby.', '{"question":"How old was Jairus'' daughter?","wrong_answer":"A baby","correct_answer":"Twelve years old"}'::jsonb, 'Daughters in stories are pictured as small.', 'Offer "A baby" beside "Twelve years old" and ask the child to choose.', 'Read Mark 5:42 and write 12 on the board.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.RAISING_OF_JAIRUS_DAUGHT.JAIRUS.M_C3_JAI_ALL_DISCIPLES', 'CRES.G3.THE_LI.RAISING_OF_JAIRUS_DAUGHT.JAIRUS', 'Thinks all twelve disciples went into the house.', '{"question":"Which disciples did Jesus take with him?","wrong_answer":"All twelve","correct_answer":"Peter, James and John"}'::jsonb, 'Disciples usually travel together.', 'Offer "All twelve" beside "Peter, James and John" and ask the child to choose.', 'Read Mark 5:37 and hold up three name cards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.RAISING_OF_JAIRUS_DAUGHT.JAIRUS.M_C3_JAI_GIVE_UP', 'CRES.G3.THE_LI.RAISING_OF_JAIRUS_DAUGHT.JAIRUS', 'Thinks Jairus should have stopped asking Jesus once the girl died.', '{"question":"What did Jesus tell Jairus when the messengers came?","wrong_answer":"Go home, it is too late","correct_answer":"Don''t be afraid; just believe"}'::jsonb, 'Death seems to end all hope.', 'Offer "Go home, it is too late" beside "Don''t be afraid; just believe" and ask the child to choose.', 'Read Mark 5:36. Faith keeps trusting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.EASTER.EASTER.M_C3_EAS_BIRTH', 'CRES.G3.THE_LI.EASTER.EASTER', 'Thinks Easter celebrates the birth of Jesus.', '{"question":"What do Christians remember at Easter?","wrong_answer":"The birth of Jesus","correct_answer":"The death and resurrection of Jesus"}'::jsonb, 'Christmas and Easter are both church holidays.', 'Offer "The birth of Jesus" beside "The death and resurrection of Jesus" and ask the child to choose.', 'Put Christmas and Easter cards side by side: birth, and death and rising.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.EASTER.EASTER.M_C3_EAS_TOMB_FULL', 'CRES.G3.THE_LI.EASTER.EASTER', 'Thinks the women found Jesus'' body in the tomb.', '{"question":"What did the women find at the tomb (Matthew 28:6)?","wrong_answer":"Jesus'' body","correct_answer":"The tomb was empty; the angel said he had risen"}'::jsonb, 'A tomb holds a body.', 'Offer "Jesus'' body" beside "The tomb was empty; the angel said he had risen" and ask the child to choose.', 'Read Matthew 28:6 and show an empty tomb picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.EASTER.EASTER.M_C3_EAS_DAYS', 'CRES.G3.THE_LI.EASTER.EASTER', 'Thinks Jesus rose on Good Friday.', '{"question":"On which day did Jesus rise from the dead?","wrong_answer":"Good Friday","correct_answer":"Easter Sunday (the third day)"}'::jsonb, 'Good Friday is the best-known Easter day.', 'Offer "Good Friday" beside "Easter Sunday (the third day)" and ask the child to choose.', 'Draw three days: Friday death, Saturday tomb, Sunday risen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_LI.EASTER.EASTER.M_C3_EAS_HOLIDAY', 'CRES.G3.THE_LI.EASTER.EASTER', 'Thinks Easter is important only because there is no school.', '{"question":"Why is Easter important to Christians?","wrong_answer":"Because there is no school","correct_answer":"It remembers that Jesus died and rose again for us"}'::jsonb, 'The holiday is what the child experiences most.', 'Offer "Because there is no school" beside "It remembers that Jesus died and rose again for us" and ask the child to choose.', 'Ask what happens in church at Easter and why.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.HONESTY.ANANIAS.M_C3_ANA_KEPT_WRONG', 'CRES.G3.CHRIST.HONESTY.ANANIAS', 'Thinks the sin was keeping part of the money.', '{"question":"What was the wrong thing Ananias and Sapphira did?","wrong_answer":"Keeping some money","correct_answer":"Lying that they had given all the money"}'::jsonb, 'Keeping money for oneself sounds selfish.', 'Offer "Keeping some money" beside "Lying that they had given all the money" and ask the child to choose.', 'Read Acts 5:4. Peter said the money was theirs; the wrong was the lie.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.HONESTY.ANANIAS.M_C3_ANA_LIE_PEOPLE', 'CRES.G3.CHRIST.HONESTY.ANANIAS', 'Thinks lying is only wrong when people find out.', '{"question":"Who did Peter say Ananias lied to?","wrong_answer":"Only to Peter","correct_answer":"To God"}'::jsonb, 'Children fear being caught by adults.', 'Offer "Only to Peter" beside "To God" and ask the child to choose.', 'Read Acts 5:4. God knows even when no one else does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.HONESTY.ANANIAS.M_C3_ANA_PICK_FOUND', 'CRES.G3.CHRIST.HONESTY.ANANIAS', 'Thinks finding someone''s pen means it becomes yours.', '{"question":"You find a pen under a desk. Whose is it?","wrong_answer":"Mine, I found it","correct_answer":"It belongs to its owner; give it to the teacher"}'::jsonb, '"Finders keepers" is a playground rule.', 'Offer "Mine, I found it" beside "It belongs to its owner; give it to the teacher" and ask the child to choose.', 'Role-play returning a found item. Say how the owner feels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.HONESTY.ANANIAS.M_C3_ANA_BORROW_KEEP', 'CRES.G3.CHRIST.HONESTY.ANANIAS', 'Thinks borrowing without asking is fine if you return it.', '{"question":"Can you take a friend''s crayon without asking?","wrong_answer":"Yes, if I give it back","correct_answer":"No, ask first"}'::jsonb, 'Returning seems to make it right.', 'Offer "Yes, if I give it back" beside "No, ask first" and ask the child to choose.', 'Practise asking: "May I use your crayon?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.THANKFULNESS.THANK_GOD.M_C3_THK_ONLY_GIFTS', 'CRES.G3.CHRIST.THANKFULNESS.THANK_GOD', 'Thinks we thank God only when we get a gift or something new.', '{"question":"When should we thank God?","wrong_answer":"Only when we get a gift","correct_answer":"Every day, for life, family, food and his love"}'::jsonb, 'Thank you is said when receiving presents.', 'Offer "Only when we get a gift" beside "Every day, for life, family, food and his love" and ask the child to choose.', 'List everyday things to thank God for: waking up, food, family.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.THANKFULNESS.THANK_GOD.M_C3_THK_ONLY_CHURCH', 'CRES.G3.CHRIST.THANKFULNESS.THANK_GOD', 'Thinks thanking God is only done in church.', '{"question":"Name a way of thanking God at home.","wrong_answer":"There is none, only in church","correct_answer":"Praying (saying grace, singing)"}'::jsonb, 'Worship is seen at church.', 'Offer "There is none, only in church" beside "Praying (saying grace, singing)" and ask the child to choose.', 'Practise saying grace before a snack in class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.THANKFULNESS.THANK_GOD.M_C3_THK_TEACHER_PAID', 'CRES.G3.CHRIST.THANKFULNESS.THANK_GOD', 'Thinks we need not thank God for teachers because they are paid.', '{"question":"Why can we thank God for our teachers?","wrong_answer":"We cannot, they are paid","correct_answer":"They teach and guide us"}'::jsonb, 'Payment seems to cancel the gift.', 'Offer "We cannot, they are paid" beside "They teach and guide us" and ask the child to choose.', 'Ask what a teacher did for the child this week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.THANKFULNESS.THANK_GOD.M_C3_THK_PSALM', 'CRES.G3.CHRIST.THANKFULNESS.THANK_GOD', 'Misquotes Psalm 136:1 as "Give thanks because we are good".', '{"question":"Complete Psalm 136:1: Give thanks to the Lord, for...","wrong_answer":"we are good","correct_answer":"he is good; his love endures forever"}'::jsonb, 'The child puts himself at the centre.', 'Offer "we are good" beside "he is good; his love endures forever" and ask the child to choose.', 'Say the verse together with actions.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.FORGIVENESS.UNFORGIVING_SERVANT.M_C3_FOR_SEVEN', 'CRES.G3.CHRIST.FORGIVENESS.UNFORGIVING_SERVANT', 'Says Jesus told Peter to forgive seven times.', '{"question":"How many times did Jesus say we should forgive?","wrong_answer":"Seven times","correct_answer":"Seventy-seven times (always)"}'::jsonb, 'Seven is the number Peter suggested.', 'Offer "Seven times" beside "Seventy-seven times (always)" and ask the child to choose.', 'Read Matthew 18:21-22. Seventy-seven means keep forgiving.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.FORGIVENESS.UNFORGIVING_SERVANT.M_C3_FOR_KING_REFUSED', 'CRES.G3.CHRIST.FORGIVENESS.UNFORGIVING_SERVANT', 'Thinks the king refused to forgive the first servant.', '{"question":"What did the king do when the servant begged?","wrong_answer":"He refused","correct_answer":"He forgave the whole debt"}'::jsonb, 'The child mixes the king with the unforgiving servant.', 'Offer "He refused" beside "He forgave the whole debt" and ask the child to choose.', 'Act out both scenes in order with three children.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.FORGIVENESS.UNFORGIVING_SERVANT.M_C3_FOR_SMALL_DEBT', 'CRES.G3.CHRIST.FORGIVENESS.UNFORGIVING_SERVANT', 'Thinks the fellow servant owed more than the first servant.', '{"question":"Who owed more money?","wrong_answer":"The fellow servant","correct_answer":"The first servant (a huge debt)"}'::jsonb, 'The child does not track the sizes.', 'Offer "The fellow servant" beside "The first servant (a huge debt)" and ask the child to choose.', 'Draw a mountain of coins and a small pile.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.FORGIVENESS.UNFORGIVING_SERVANT.M_C3_FOR_FORGET', 'CRES.G3.CHRIST.FORGIVENESS.UNFORGIVING_SERVANT', 'Thinks forgiving means the wrong never happened or must be forgotten at once.', '{"question":"A friend says sorry for breaking your pencil. What does forgiving mean?","wrong_answer":"Pretend it never happened","correct_answer":"Stop being angry and not pay him back"}'::jsonb, 'Adults say "forgive and forget".', 'Offer "Pretend it never happened" beside "Stop being angry and not pay him back" and ask the child to choose.', 'Say: forgiving means letting go of anger and not taking revenge. If someone keeps hurting you, tell an adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.TRUST.TRUSTED_ADULTS.M_C3_TRU_SECRET_KEEP', 'CRES.G3.CHRIST.TRUST.TRUSTED_ADULTS', 'Thinks a secret about touching should be kept if an adult asks.', '{"question":"A grown-up touches you in a bad way and says \"keep it a secret\". What do you do?","wrong_answer":"Keep the secret","correct_answer":"Tell a trusted adult at once"}'::jsonb, 'Children are taught to obey adults and keep promises.', 'Offer "Keep the secret" beside "Tell a trusted adult at once" and ask the child to choose.', 'Teach: no secrets about touching. Tell a parent, teacher or call 116.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.TRUST.TRUSTED_ADULTS.M_C3_TRU_OWN_FAULT', 'CRES.G3.CHRIST.TRUST.TRUSTED_ADULTS', 'Thinks it is the child''s fault if someone touches him or her wrongly.', '{"question":"If someone touches a child in a bad way, whose fault is it?","wrong_answer":"The child''s","correct_answer":"Never the child''s; the adult did wrong"}'::jsonb, 'Children often feel blamed when bad things happen.', 'Offer "The child''s" beside "Never the child''s; the adult did wrong" and ask the child to choose.', 'Say clearly and kindly: it is never your fault. Telling is right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.TRUST.TRUSTED_ADULTS.M_C3_TRU_KNOWN_SAFE', 'CRES.G3.CHRIST.TRUST.TRUSTED_ADULTS', 'Thinks anyone known to the family is always safe.', '{"question":"Can someone you know ask you to keep a secret touch?","wrong_answer":"No, people I know are always safe","correct_answer":"Yes, it can happen; tell a trusted adult"}'::jsonb, 'Danger is taught as coming from strangers only.', 'Offer "No, people I know are always safe" beside "Yes, it can happen; tell a trusted adult" and ask the child to choose.', 'Teach the rule: anyone, known or unknown. Name several trusted adults.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.TRUST.TRUSTED_ADULTS.M_C3_TRU_TELL_ONCE', 'CRES.G3.CHRIST.TRUST.TRUSTED_ADULTS', 'Thinks if one adult does not listen, there is nobody else to tell.', '{"question":"You told an adult and they did not help. What next?","wrong_answer":"Stop telling","correct_answer":"Tell another trusted adult (a teacher, head teacher, police, 116)"}'::jsonb, 'Children give up after one try.', 'Offer "Stop telling" beside "Tell another trusted adult (a teacher, head teacher, police, 116)" and ask the child to choose.', 'List three or more people to tell and Childline 116. Keep telling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.RESPONSIBILITY.CHORES.M_C3_RES_PAY', 'CRES.G3.CHRIST.RESPONSIBILITY.CHORES', 'Thinks a child should be paid or given sweets for every chore.', '{"question":"Mother asks you to sweep the house. Should you ask for money first?","wrong_answer":"Yes, work should be paid","correct_answer":"No, I help because I am part of the family"}'::jsonb, 'Adults are paid for work, so the child expects the same.', 'Offer "Yes, work should be paid" beside "No, I help because I am part of the family" and ask the child to choose.', 'Read Colossians 3:23. Talk about what parents do for children without pay.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.RESPONSIBILITY.CHORES.M_C3_RES_GIRLS_ONLY', 'CRES.G3.CHRIST.RESPONSIBILITY.CHORES', 'Thinks chores like cooking and washing are only for girls.', '{"question":"Can a boy wash utensils at home?","wrong_answer":"No, it is girls'' work","correct_answer":"Yes, boys and girls can do all chores"}'::jsonb, 'At home chores are often split by gender.', 'Offer "No, it is girls'' work" beside "Yes, boys and girls can do all chores" and ask the child to choose.', 'List chores and ask who can do each: everyone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.RESPONSIBILITY.CHORES.M_C3_RES_TELL_TALES', 'CRES.G3.CHRIST.RESPONSIBILITY.CHORES', 'Thinks correcting a wrongdoer means shouting at or beating them.', '{"question":"A classmate is writing on the wall. What is a responsible thing to do?","wrong_answer":"Beat him","correct_answer":"Tell him kindly to stop, or tell the teacher"}'::jsonb, 'Correction at home sometimes comes with shouting.', 'Offer "Beat him" beside "Tell him kindly to stop, or tell the teacher" and ask the child to choose.', 'Role-play kind words: "Please stop, that is wrong." Then tell a teacher.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.CHRIST.RESPONSIBILITY.CHORES.M_C3_RES_ONLY_WATCHED', 'CRES.G3.CHRIST.RESPONSIBILITY.CHORES', 'Thinks chores need doing only when a parent is watching.', '{"question":"Your parent is away. Should you still do your chores?","wrong_answer":"No, nobody is watching","correct_answer":"Yes, I work as for the Lord"}'::jsonb, 'Children work to please the adult present.', 'Offer "No, nobody is watching" beside "Yes, I work as for the Lord" and ask the child to choose.', 'Read Colossians 3:23 again: God sees.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_CH.PRAYER.LORDS_PRAYER.M_C3_PRA_WHO_TAUGHT', 'CRES.G3.THE_CH.PRAYER.LORDS_PRAYER', 'Thinks the pastor or Moses wrote the Lord''s Prayer.', '{"question":"Who taught the Lord''s Prayer?","wrong_answer":"The pastor","correct_answer":"Jesus"}'::jsonb, 'The child hears it led by the pastor.', 'Offer "The pastor" beside "Jesus" and ask the child to choose.', 'Read Matthew 6:9: "This, then, is how you should pray."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_CH.PRAYER.LORDS_PRAYER.M_C3_PRA_ORDER', 'CRES.G3.THE_CH.PRAYER.LORDS_PRAYER', 'Puts "give us today our daily bread" first.', '{"question":"What are the first words of the Lord''s Prayer?","wrong_answer":"Give us today our daily bread","correct_answer":"Our Father in heaven"}'::jsonb, 'Asking for bread is the most concrete line.', 'Offer "Give us today our daily bread" beside "Our Father in heaven" and ask the child to choose.', 'Use line cards on a washing line and put them in order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_CH.PRAYER.LORDS_PRAYER.M_C3_PRA_ONE_POSTURE', 'CRES.G3.THE_CH.PRAYER.LORDS_PRAYER', 'Thinks there is only one right posture and others are wrong.', '{"question":"Is kneeling the only right way to pray?","wrong_answer":"Yes","correct_answer":"No, Christians kneel, stand or bow; all can show respect"}'::jsonb, 'The child has seen one posture at his church.', 'Offer "Yes" beside "No, Christians kneel, stand or bow; all can show respect" and ask the child to choose.', 'Show pictures of people praying in different postures. Ask what they share: respect.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_CH.PRAYER.LORDS_PRAYER.M_C3_PRA_PLAY_PRAY', 'CRES.G3.THE_CH.PRAYER.LORDS_PRAYER', 'Thinks it is fine to play or look around while others pray.', '{"question":"The class is praying. What should you do?","wrong_answer":"Keep playing quietly","correct_answer":"Stop, close my eyes or bow, and pray too"}'::jsonb, 'Prayer time seems a pause in activity.', 'Offer "Keep playing quietly" beside "Stop, close my eyes or bow, and pray too" and ask the child to choose.', 'Practise a short class prayer with a respectful posture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_CH.THE_HOLY_SPIRIT.PENTECOST.M_C3_PEN_REAL_FIRE', 'CRES.G3.THE_CH.THE_HOLY_SPIRIT.PENTECOST', 'Thinks the disciples'' heads were burnt by real fire.', '{"question":"What rested on the disciples at Pentecost?","wrong_answer":"Real fire that burnt them","correct_answer":"What looked like tongues of fire, without burning them"}'::jsonb, 'Fire always burns in the child''s experience.', 'Offer "Real fire that burnt them" beside "What looked like tongues of fire, without burning them" and ask the child to choose.', 'Read Acts 2:3: what seemed to be tongues of fire.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_CH.THE_HOLY_SPIRIT.PENTECOST.M_C3_PEN_STORM', 'CRES.G3.THE_CH.THE_HOLY_SPIRIT.PENTECOST', 'Thinks a real storm blew the house down.', '{"question":"What did the disciples hear at Pentecost?","wrong_answer":"A storm that blew the house down","correct_answer":"A sound like a violent wind from heaven"}'::jsonb, 'Wind is linked with storms and damage.', 'Offer "A storm that blew the house down" beside "A sound like a violent wind from heaven" and ask the child to choose.', 'Read Acts 2:2: a sound like wind, filling the house.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_CH.THE_HOLY_SPIRIT.PENTECOST.M_C3_PEN_CHRISTMAS', 'CRES.G3.THE_CH.THE_HOLY_SPIRIT.PENTECOST', 'Mixes Pentecost with Christmas or Easter.', '{"question":"What happened on the day of Pentecost?","wrong_answer":"Jesus was born","correct_answer":"The Holy Spirit came on the disciples"}'::jsonb, 'All church festivals feel alike.', 'Offer "Jesus was born" beside "The Holy Spirit came on the disciples" and ask the child to choose.', 'Make a three-card line: Christmas (birth), Easter (rose), Pentecost (Holy Spirit came).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_CH.THE_HOLY_SPIRIT.PENTECOST.M_C3_PEN_WORK_MAGIC', 'CRES.G3.THE_CH.THE_HOLY_SPIRIT.PENTECOST', 'Thinks the Holy Spirit''s work is to give magic powers or riches.', '{"question":"Name a work of the Holy Spirit in a Christian''s life.","wrong_answer":"He makes people rich","correct_answer":"He guides, comforts and helps Christians"}'::jsonb, 'Power is pictured as magic in stories.', 'Offer "He makes people rich" beside "He guides, comforts and helps Christians" and ask the child to choose.', 'List the roles from John 14:26 and Luke 24:49 in simple words: helper, teacher, comforter, strength.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_CH.THE_HOLY_SPIRIT.FRUIT_SPIRIT.M_C3_FRU_EAT', 'CRES.G3.THE_CH.THE_HOLY_SPIRIT.FRUIT_SPIRIT', 'Thinks the fruit of the Spirit are real fruits like mangoes.', '{"question":"Is a mango a fruit of the Holy Spirit?","wrong_answer":"Yes","correct_answer":"No, the fruit of the Spirit are ways of behaving like love and joy"}'::jsonb, 'The word fruit means food to the child.', 'Offer "Yes" beside "No, the fruit of the Spirit are ways of behaving like love and joy" and ask the child to choose.', 'Draw a tree with words on it: love, joy, peace. Say: these grow in our lives.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_CH.THE_HOLY_SPIRIT.FRUIT_SPIRIT.M_C3_FRU_MONEY', 'CRES.G3.THE_CH.THE_HOLY_SPIRIT.FRUIT_SPIRIT', 'Names money or cleverness as a fruit of the Spirit.', '{"question":"Which is a fruit of the Spirit: patience or money?","wrong_answer":"Money","correct_answer":"Patience"}'::jsonb, 'Good things in life feel like gifts from God.', 'Offer "Money" beside "Patience" and ask the child to choose.', 'Read Galatians 5:22-23 and circle each fruit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_CH.THE_HOLY_SPIRIT.FRUIT_SPIRIT.M_C3_FRU_STORY_MATCH', 'CRES.G3.THE_CH.THE_HOLY_SPIRIT.FRUIT_SPIRIT', 'Cannot match an action to its fruit, calling waiting your turn "joy".', '{"question":"Juma waits calmly for his turn on the swing. Which fruit is this?","wrong_answer":"Joy","correct_answer":"Patience"}'::jsonb, 'All good behaviour feels the same to the child.', 'Offer "Joy" beside "Patience" and ask the child to choose.', 'Act out each fruit and guess its name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G3.THE_CH.THE_HOLY_SPIRIT.FRUIT_SPIRIT.M_C3_FRU_ONE', 'CRES.G3.THE_CH.THE_HOLY_SPIRIT.FRUIT_SPIRIT', 'Thinks there is only one fruit of the Spirit, love.', '{"question":"How many fruit of the Spirit are named in Galatians 5:22-23?","wrong_answer":"One, love","correct_answer":"Nine"}'::jsonb, 'Love is mentioned most in church.', 'Offer "One, love" beside "Nine" and ask the child to choose.', 'Count the nine fruit on the board.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
